public with sharing class ContactLookupAction {
    public class Request {
        @InvocableVariable(required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable
        public Id contactId;

        @InvocableVariable
        public Boolean found;
    }

    @InvocableMethod(label='Find Contact by Email')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        List<String> orderedEmails = new List<String>();
        Set<String> emailsToQuery = new Set<String>();

        for (Request request : requests) {
            String normalizedEmail =
                request == null || String.isBlank(request.email)
                ? null
                : request.email.trim().toLowerCase();

            orderedEmails.add(normalizedEmail);
            if (normalizedEmail != null) {
                emailsToQuery.add(normalizedEmail);
            }
        }

        Map<String, Id> contactIdsByEmail = new Map<String, Id>();

        if (!emailsToQuery.isEmpty()) {
            // Email comparisons in SOQL are case-insensitive.
            // User mode also enforces object and field permissions.
            for (Contact candidate : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :emailsToQuery
                WITH USER_MODE
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                String normalizedEmail = candidate.Email.toLowerCase();

                // The first contact for each email is the earliest created.
                // Id provides a deterministic tie-breaker.
                if (!contactIdsByEmail.containsKey(normalizedEmail)) {
                    contactIdsByEmail.put(normalizedEmail, candidate.Id);
                }
            }
        }

        for (String normalizedEmail : orderedEmails) {
            Result result = new Result();
            result.contactId = normalizedEmail == null
                ? null
                : contactIdsByEmail.get(normalizedEmail);
            result.found = result.contactId != null;
            results.add(result);
        }

        return results;
    }
}
