public with sharing class OrderPayloadParser {
    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines = new List<Line>();
        public Decimal total = 0;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {
    }

    public static OrderPayloadParser.Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('The request body must not be blank.');
        }

        try {
            // Check the entire document, including any trailing content.
            JSONParser validator = JSON.createParser(body);
            if (validator.nextToken() != JSONToken.START_OBJECT) {
                throw new PayloadException('The payload must be a JSON object.');
            }
            validator.skipChildren();
            if (validator.nextToken() != null) {
                throw new PayloadException(
                    'The payload must contain exactly one JSON object.'
                );
            }

            Map<String, Object> payload = objectValue(
                JSON.deserializeUntyped(body),
                'payload'
            );

            Order order = new Order();
            order.orderNumber = stringValue(payload.get('number'), 'number');
            if (String.isBlank(order.orderNumber)) {
                throw new PayloadException('number is required and must not be blank.');
            }

            String dateText = stringValue(payload.get('date'), 'date');
            if (dateText != null) {
                if (!Pattern.matches('^[0-9]{4}-[0-9]{2}-[0-9]{2}$', dateText)) {
                    throw new PayloadException('date must use yyyy-MM-dd format.');
                }
                order.orderDate = Date.valueOf(dateText);
            }

            order.currencyCode = stringValue(payload.get('currency'), 'currency');

            Object customerValue = payload.get('customer');
            if (customerValue != null) {
                Map<String, Object> customer = objectValue(
                    customerValue,
                    'customer'
                );
                order.customerEmail = stringValue(
                    customer.get('email'),
                    'customer.email'
                );
            }

            Object linesValue = payload.get('lines');
            if (linesValue != null) {
                if (!(linesValue instanceof List<Object>)) {
                    throw new PayloadException('lines must be a JSON array.');
                }

                List<Object> rawLines = (List<Object>) linesValue;
                for (Integer index = 0; index < rawLines.size(); index++) {
                    String path = 'lines[' + String.valueOf(index) + ']';
                    Map<String, Object> rawLine = objectValue(
                        rawLines[index],
                        path
                    );

                    Line line = new Line();
                    line.sku = stringValue(rawLine.get('sku'), path + '.sku');
                    if (line.sku == null) {
                        throw new PayloadException(path + '.sku is required.');
                    }

                    Decimal quantity = decimalValue(
                        rawLine.get('quantity'),
                        path + '.quantity'
                    );
                    if (
                        quantity == null ||
                        quantity <= 0 ||
                        quantity > 2147483647 ||
                        quantity != quantity.setScale(0, RoundingMode.DOWN)
                    ) {
                        throw new PayloadException(
                            path + '.quantity must be a positive Integer.'
                        );
                    }
                    line.quantity = quantity.intValue();

                    line.unitPrice = decimalValue(
                        rawLine.get('unitPrice'),
                        path + '.unitPrice'
                    );
                    if (line.unitPrice == null || line.unitPrice < 0) {
                        throw new PayloadException(
                            path + '.unitPrice is required and must not be negative.'
                        );
                    }

                    line.discount = decimalValue(
                        rawLine.get('discount'),
                        path + '.discount'
                    );
                    if (line.discount == null) {
                        line.discount = 0;
                    }
                    if (line.discount < 0 || line.discount > 1) {
                        throw new PayloadException(
                            path + '.discount must be between 0 and 1.'
                        );
                    }

                    line.lineTotal = (
                        quantity * line.unitPrice * (1 - line.discount)
                    ).setScale(2, RoundingMode.HALF_UP);

                    order.lines.add(line);
                    order.total += line.lineTotal;
                }
            }

            return order;
        } catch (PayloadException ex) {
            throw ex;
        } catch (Exception ex) {
            // Normalize JSON, conversion, and arithmetic failures.
            throw new PayloadException('Invalid order payload.');
        }
    }

    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        if (order == null || order.total == null) {
            throw new PayloadException('An order with a total is required.');
        }

        Integer lineCount = order.lines == null ? 0 : order.lines.size();

        return JSON.serialize(new Map<String, Object>{
            'number' => order.orderNumber,
            'status' => 'RECEIVED',
            'lineCount' => lineCount,
            'total' => order.total
        });
    }

    private static Map<String, Object> objectValue(
        Object value,
        String fieldName
    ) {
        if (!(value instanceof Map<String, Object>)) {
            throw new PayloadException(fieldName + ' must be a JSON object.');
        }
        return (Map<String, Object>) value;
    }

    private static String stringValue(Object value, String fieldName) {
        if (value == null) {
            return null;
        }
        if (!(value instanceof String)) {
            throw new PayloadException(fieldName + ' must be a JSON string.');
        }
        return (String) value;
    }

    private static Decimal decimalValue(Object value, String fieldName) {
        if (value == null) {
            return null;
        }
        if (
            !(value instanceof Integer) &&
            !(value instanceof Long) &&
            !(value instanceof Decimal) &&
            !(value instanceof Double)
        ) {
            throw new PayloadException(fieldName + ' must be a JSON number.');
        }
        return Decimal.valueOf(String.valueOf(value));
    }
}
