public with sharing class PicklistService {
    private static Map<String, Schema.SObjectType> objectTypesByName;

    private static Map<String, Map<String, Schema.SObjectField>> fieldsByObjectName =
        new Map<String, Map<String, Schema.SObjectField>>();

    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    public class PicklistServiceException extends Exception {
    }

    /**
     * Returns active, field-level picklist values in their defined order.
     * Values are not filtered by record type.
     */
    public static List<PicklistService.Option> activeOptions(
        String objectApiName,
        String fieldApiName
    ) {
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name must not be blank.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name must not be blank.');
        }

        String objectKey = objectApiName.trim().toLowerCase();
        String fieldKey = fieldApiName.trim().toLowerCase();

        // Normalize keys explicitly and cache metadata for this transaction.
        if (objectTypesByName == null) {
            objectTypesByName = new Map<String, Schema.SObjectType>();
            Map<String, Schema.SObjectType> globalDescribe = Schema.getGlobalDescribe();

            for (String apiName : globalDescribe.keySet()) {
                objectTypesByName.put(
                    apiName.toLowerCase(),
                    globalDescribe.get(apiName)
                );
            }
        }

        Schema.SObjectType objectType = objectTypesByName.get(objectKey);
        if (objectType == null) {
            throw new PicklistServiceException(
                'Object does not exist: ' + objectApiName.trim()
            );
        }

        if (!fieldsByObjectName.containsKey(objectKey)) {
            Map<String, Schema.SObjectField> describedFields =
                objectType.getDescribe().fields.getMap();
            Map<String, Schema.SObjectField> normalizedFields =
                new Map<String, Schema.SObjectField>();

            for (String apiName : describedFields.keySet()) {
                normalizedFields.put(
                    apiName.toLowerCase(),
                    describedFields.get(apiName)
                );
            }

            fieldsByObjectName.put(objectKey, normalizedFields);
        }

        Schema.SObjectField fieldToken =
            fieldsByObjectName.get(objectKey).get(fieldKey);

        if (fieldToken == null) {
            throw new PicklistServiceException(
                'Field does not exist on ' + objectApiName.trim() +
                ': ' + fieldApiName.trim()
            );
        }

        Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();
        Schema.DisplayType fieldType = fieldDescribe.getType();

        if (fieldType != Schema.DisplayType.Picklist &&
            fieldType != Schema.DisplayType.MultiPicklist) {
            throw new PicklistServiceException(
                'Field is not a picklist or multi-select picklist: ' +
                objectApiName.trim() + '.' + fieldApiName.trim()
            );
        }

        List<PicklistService.Option> options =
            new List<PicklistService.Option>();

        for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
            if (entry.isActive()) {
                options.add(new Option(
                    entry.getValue(),
                    entry.getLabel(),
                    entry.isDefaultValue()
                ));
            }
        }

        return options;
    }
}
