// These system-maintained totals must include all opportunities,
// regardless of the initiating user's record visibility.
public without sharing class OpportunityPipelineHandler {
    public static void handleAfter(
        System.TriggerOperation operation,
        Map<Id, Opportunity> newRecords,
        Map<Id, Opportunity> oldRecords
    ) {
        Set<Id> affectedAccountIds = new Set<Id>();

        switch on operation {
            when AFTER_INSERT, AFTER_UNDELETE {
                for (Opportunity opportunity : newRecords.values()) {
                    addOpenAccount(affectedAccountIds, opportunity);
                }
            }
            when AFTER_DELETE {
                for (Opportunity opportunity : oldRecords.values()) {
                    addOpenAccount(affectedAccountIds, opportunity);
                }
            }
            when AFTER_UPDATE {
                for (Opportunity opportunity : newRecords.values()) {
                    Opportunity previous = oldRecords.get(opportunity.Id);

                    // In particular, ignore rating-only updates made by
                    // AccountTrigger. Do not use a transaction-wide guard:
                    // later meaningful DML must recalculate the totals.
                    if (
                        opportunity.AccountId != previous.AccountId ||
                        opportunity.IsClosed != previous.IsClosed ||
                        opportunity.Amount != previous.Amount
                    ) {
                        addOpenAccount(affectedAccountIds, previous);
                        addOpenAccount(affectedAccountIds, opportunity);
                    }
                }
            }
        }

        if (affectedAccountIds.isEmpty()) {
            return;
        }

        recalculate(affectedAccountIds);
    }

    private static void addOpenAccount(
        Set<Id> accountIds,
        Opportunity opportunity
    ) {
        if (opportunity.AccountId != null && !opportunity.IsClosed) {
            accountIds.add(opportunity.AccountId);
        }
    }

    private static void recalculate(Set<Id> affectedAccountIds) {
        // Lock existing parents before reading their totals and aggregating.
        // This serializes competing recalculations for the same accounts.
        Map<Id, Account> accounts = new Map<Id, Account>([
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :affectedAccountIds
            FOR UPDATE
        ]);

        if (accounts.isEmpty()) {
            return;
        }

        Set<Id> existingAccountIds = accounts.keySet();
        Map<Id, AggregateResult> totalsByAccount =
            new Map<Id, AggregateResult>();

        for (AggregateResult totals : [
            SELECT AccountId,
                   SUM(Amount) pipelineAmount,
                   COUNT(Id) opportunityCount
            FROM Opportunity
            WHERE AccountId IN :existingAccountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            totalsByAccount.put((Id) totals.get('AccountId'), totals);
        }

        List<Account> updates = new List<Account>();

        for (Account account : accounts.values()) {
            Decimal pipelineAmount = 0;
            Integer opportunityCount = 0;

            AggregateResult totals = totalsByAccount.get(account.Id);
            if (totals != null) {
                Decimal summedAmount =
                    (Decimal) totals.get('pipelineAmount');

                // SUM ignores null amounts and can return null when
                // every open opportunity has a blank amount.
                pipelineAmount = summedAmount == null ? 0 : summedAmount;
                opportunityCount =
                    (Integer) totals.get('opportunityCount');
            }

            // Missing aggregate groups intentionally produce 0 and 0.
            // Avoid unnecessary Account DML and its legacy side effects.
            if (
                account.FB_Open_Pipeline__c != pipelineAmount ||
                account.FB_Open_Opportunities__c != opportunityCount
            ) {
                updates.add(new Account(
                    Id = account.Id,
                    FB_Open_Pipeline__c = pipelineAmount,
