// Runs in system context so retention applies to all integration logs.
public without sharing class LogPurgeJob
    implements Schedulable, Database.Batchable<SObject> {

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext context) {
        // Batch Apex handles volumes beyond a single transaction's DML limits.
        Database.executeBatch(new LogPurgeJob(), 200);
    }

    public Database.QueryLocator start(Database.BatchableContext context) {
        Datetime runTime = System.now();
        Datetime standardCutoff = runTime.addDays(-30);
        Datetime errorCutoff = runTime.addDays(-180);

        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (
                CreatedDate < :standardCutoff
                AND (Level__c = null OR Level__c != 'ERROR')
            )
            OR (
                CreatedDate < :errorCutoff
                AND Level__c = 'ERROR'
            )
        ]);
    }

    public void execute(
        Database.BatchableContext context,
        List<SObject> scope
    ) {
        // Failures are surfaced through the batch job's error reporting.
        delete scope;
    }

    public void finish(Database.BatchableContext context) {
    }

    public static Id scheduleNightly() {
        // Salesforce interprets this time in the scheduling user's time zone.
        return System.schedule(
            'Log purge (nightly)',
            '0 0 2 * * ?',
            new LogPurgeJob()
        );
    }
}
