            Assert.areEqual(
                new List<String>{
                    'selectById',
                    'applyDiscount',
                    'commitWork'
                },
                calls,
                'Select once, apply once, then commit once, in that order.'
            );

            verifySelectionAndApplication(percentage);

            ((fflib_ISObjectUnitOfWork) mocks.verify(uow, 1))
                .commitWork();
        }
    }

    private class RecordingAnswer implements fflib_Answer {
        private List<String> calls;
        private String operation;
        private Object result;
        private Exception failure;

        private RecordingAnswer(
            List<String> calls,
            String operation,
            Object result
        ) {
            this.calls = calls;
            this.operation = operation;
            this.result = result;
        }

        public Object answer(fflib_InvocationOnMock invocation) {
            calls.add(operation);
            if (failure != null) {
                throw failure;
            }
            return result;
        }
    }

    private class DiscountFailureException extends Exception {}
}
