                LastName = 'Cleared birthdate',
                Birthdate = today.addDays(-1)
            )
        };
        Map<Id, SObject> oldRecords = snapshot(records);

        records[0].Birthdate = today.addDays(1);
        // An unchanged future Birthdate must also be rejected.
        records[2].Birthdate = today;
