        assertNoErrors(records[2]);
        assertNoErrors(records[3]);
        assertNoErrors(records[4]);
    }

    private static Map<Id, SObject> snapshot(List<Contact> records) {
        Map<Id, SObject> oldRecords = new Map<Id, SObject>();
        for (Contact record : records) {
            oldRecords.put(record.Id, record.clone(true, false, false, false));
        }
        return oldRecords;
