        Integer dmlBefore = Limits.getDmlStatements();

        fflib_SObjectDomain.triggerHandler(Contacts.class);

        Assert.areEqual(
            queriesBefore,
            Limits.getQueries(),
            'The unit-test trigger path must not execute SOQL.'
        );
        Assert.areEqual(
            dmlBefore,
            Limits.getDmlStatements(),
            'The unit-test trigger path must not execute DML.'
        );
    }

