public with sharing class ContactEmailMatcher {
    public class Request {
        @InvocableVariable(required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable
        public Id contactId;
    }

    @InvocableMethod(label='Match Contact by Email')
    public static List<Result> match(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        List<String> requestKeys = new List<String>();
        Set<String> emailsToMatch = new Set<String>();

        for (Request request : requests) {
            String key = normalizeEmail(request == null ? null : request.email);
            requestKeys.add(key);
            if (key != null) {
                emailsToMatch.add(key);
            }
        }

        Map<String, Id> contactIdByEmail = new Map<String, Id>();

        if (!emailsToMatch.isEmpty()) {
            // Email comparisons in SOQL are case-insensitive. Ordering ensures
            // the first Contact retained for each email is the required match.
            for (Contact candidate : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :emailsToMatch
                WITH USER_MODE
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                String key = normalizeEmail(candidate.Email);
                if (key != null && !contactIdByEmail.containsKey(key)) {
                    contactIdByEmail.put(key, candidate.Id);
                }
            }
        }

        for (String key : requestKeys) {
            Result result = new Result();
            result.contactId = key == null ? null : contactIdByEmail.get(key);
            results.add(result);
        }

        return results;
    }

    private static String normalizeEmail(String email) {
        return String.isBlank(email) ? null : email.trim().toLowerCase();
    }
}
