```apex
/**
 * Org-wide maintenance invoked by trusted scheduled automation.
 *
 * Deliberately runs without sharing and uses system-mode DML so that record
 * ownership and the scheduling user's field permissions do not omit deals.
 * Do not expose this method through a user-facing controller.
 *
 * The requested chunking is suitable for a few thousand records, but each
 * chunk still belongs to the SAME synchronous transaction. It does not reset
 * governor limits: 10,000 DML rows, 150 DML statements, query-row and CPU limits
 * still apply, including work performed by triggers and flows.
 *
 * For larger or unpredictable volumes, use Batch Apex with a scope of 200.
 * Report its total from finish(), rather than expecting the scheduling call
 * to return the completed count synchronously.
 */
public without sharing class StaleOpportunityCloser {
    /**
     * Closes open opportunities strictly before cutoff.
     * Returns the number updated when all updates succeed.
     * DML failures propagate to the caller; they are not silently skipped.
     */
    public static Integer closeStale(Date cutoff) {
        if (cutoff == null) {
            throw new IllegalArgumentException('cutoff must not be null.');
        }

        Integer closedCount = 0;

        for (List<Opportunity> chunk : [
            SELECT Id, StageName
            FROM Opportunity
            WHERE IsClosed = false
                AND CloseDate < :cutoff
        ]) {
            for (Opportunity opportunityRecord : chunk) {
                opportunityRecord.StageName = 'Closed Lost';
            }

            // SOQL supplies at most 200 records per chunk.
            // Normal DML is all-or-none for this chunk.
            update chunk;
            closedCount += chunk.size();
        }

        return closedCount;
    }
}
