public without sharing class CasePriorityHandler {
    /*
     * Unlike the requested query inside the loop, this handler queries Accounts
     * once per batch. Up to 200 per-case queries would exceed the synchronous
     * SOQL limit of 100 queries.
     *
     * Sharing is intentionally not enforced for this trigger-only business rule,
     * so priority assignment does not depend on the creator's Account access.
     */
    public static void setCasePriorities(List<Case> newCases) {
        Set<Id> accountIds = new Set<Id>();

        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :accountIds
        ]);

        for (Case c : newCases) {
            Account account = accountsById.get(c.AccountId);

            if (account != null && account.Rating == 'Hot') {
                c.Priority = 'High';
            }
        }
    }
}
