public with sharing class DealEventPublisher {
    /**
     * Publishes one event per opportunity, preserving input order.
     * Callers must supply non-null Opportunities with persisted Ids and
     * accessible StageName and Amount fields.
     *
     * Deliberately uses one bulk EventBus.publish call instead of publishing
     * inside the loop. For Publish After Commit events, each publish call
     * counts against the transaction's 150-DML-statement limit, so individual
     * calls cannot safely handle a trigger batch of 200 Opportunities.
     *
     * Bulk publishing returns one SaveResult per event in the same order,
     * preserving the ability to identify each failed enqueue operation.
     * A successful SaveResult confirms enqueueing, not final publication.
     * These events are published only if the transaction commits.
     */
    public static List<Database.SaveResult> publishStageChanges(
        List<Opportunity> opportunities
    ) {
        if (opportunities == null || opportunities.isEmpty()) {
            return new List<Database.SaveResult>();
        }

        List<Deal_Stage_Change__e> events =
            new List<Deal_Stage_Change__e>();

        for (Opportunity opportunity : opportunities) {
            events.add(new Deal_Stage_Change__e(
                // Converting an Apex Id to String yields its 18-character form.
                Opportunity_Id__c = String.valueOf(opportunity.Id),
                Stage__c = opportunity.StageName,
                Amount__c = opportunity.Amount
            ));
        }

        return EventBus.publish(events);
    }
}
