public with sharing class FollowUpTaskService {
    /**
     * Creates one follow-up task per distinct, non-null opportunity Id.
     * Returns the opportunity Ids for which no task could be created.
     *
     * Deliberately uses one bulk insert with allOrNone=false instead of
     * inserting inside a loop. Per-record inserts would exceed the synchronous
     * limit of 150 DML statements for larger reviews. That governor-limit
     * exception cannot be caught and would roll back the transaction.
     *
     * User-mode operations enforce sharing, CRUD, and field-level security.
     * Missing or inaccessible opportunities are reported as failures.
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        failedOpportunityIds.addAll(opportunityIds);
        failedOpportunityIds.remove(null);

        if (failedOpportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        List<Opportunity> opportunities;
        try {
            opportunities = [
                SELECT Id, Name, OwnerId
                FROM Opportunity
                WHERE Id IN :failedOpportunityIds
                WITH USER_MODE
            ];
        } catch (QueryException ex) {
            // For example, the caller lacks access to a queried field.
            // No tasks have been created, so all requested Ids remain failed.
            return failedOpportunityIds;
        }

        Date dueDate = Date.today().addDays(7);
        List<Task> tasks = new List<Task>();

        for (Opportunity opportunity : opportunities) {
            tasks.add(new Task(
                WhatId = opportunity.Id,
                OwnerId = opportunity.OwnerId,
                Subject = 'Follow up: ' + opportunity.Name,
                ActivityDate = dueDate,
                Status = 'Not Started',
                Priority = 'Normal'
            ));
        }

        if (tasks.isEmpty()) {
            return failedOpportunityIds;
        }

        List<Database.SaveResult> results;
        try {
            results = Database.insert(tasks, false, AccessLevel.USER_MODE);
        } catch (DmlException ex) {
            // An operation-level DML failure leaves all requested Ids failed.
            // Ordinary record-level failures are handled through SaveResult.
            return failedOpportunityIds;
        }

        // SaveResult entries correspond to the input records by index.
        for (Integer i = 0; i < results.size(); i++) {
            if (results[i].isSuccess()) {
                failedOpportunityIds.remove(tasks[i].WhatId);
            }
        }

        return failedOpportunityIds;
    }
}
