public with sharing class LeadContactMatcher {
    /**
     * Returns contact IDs in lead order, preserving the first contact for each
     * normalized email. Blank emails never match.
     *
     * A map is preferable to nested loops here: 3,000 leads and 3,000 contacts
     * could require 9,000,000 comparisons within the transaction's CPU limit.
     * Indexing provides expected O(contacts + leads) time, using O(contacts)
     * additional space. No records are queried or modified.
     *
     * A null leads list returns an empty list. Null contacts or null list
     * elements are treated as having no match.
     */
    public static List<Id> matchByEmail(
        List<Lead> leads,
        List<Contact> contacts
    ) {
        List<Id> matches = new List<Id>();
        if (leads == null || leads.isEmpty()) {
            return matches;
        }

        Map<String, Id> firstContactIdByEmail = new Map<String, Id>();

        if (contacts != null) {
            for (Contact contactRecord : contacts) {
                if (contactRecord == null) {
                    continue;
                }

                String emailKey = normalizeEmail(contactRecord.Email);
                if (emailKey != null &&
                    !firstContactIdByEmail.containsKey(emailKey)) {
                    // Preserve the first contact even if its Id is null.
                    firstContactIdByEmail.put(emailKey, contactRecord.Id);
                }
            }
        }

        for (Lead leadRecord : leads) {
            String emailKey = leadRecord == null
                ? null
                : normalizeEmail(leadRecord.Email);

            matches.add(
                emailKey == null ? null : firstContactIdByEmail.get(emailKey)
            );
        }

        return matches;
    }

    private static String normalizeEmail(String email) {
        return String.isBlank(email) ? null : email.trim().toLowerCase();
    }
}
