public with sharing class RenewalReminderService {
    /**
     * Emails the owners of the supplied opportunities.
     *
     * Calling Messaging.sendEmail inside the loop is deliberately avoided:
     * Apex permits only 10 sendEmail invocations per transaction, so processing
     * 200 opportunities that way would exceed a governor limit. User-ID
     * recipients avoid the external-email daily allocation, not this limit.
     *
     * A single bulk call with allOrNone=false allows valid messages to proceed
     * when individual messages fail. Transaction-wide failures can still abort
     * processing.
     *
     * @return Number of messages Salesforce successfully accepted for sending.
     *         This does not confirm eventual delivery.
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Send one reminder per distinct opportunity; ignore null IDs.
        Set<Id> uniqueOpportunityIds = new Set<Id>(opportunityIds);
        uniqueOpportunityIds.remove(null);

        if (uniqueOpportunityIds.isEmpty()) {
            return 0;
        }

        List<Messaging.SingleEmailMessage> messages =
            new List<Messaging.SingleEmailMessage>();

        // Enforce the running user's sharing, object, and field permissions.
        for (Opportunity opportunity : [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :uniqueOpportunityIds
            WITH USER_MODE
        ]) {
            Messaging.SingleEmailMessage message =
                new Messaging.SingleEmailMessage();

            message.setTargetObjectId(opportunity.OwnerId);
            message.setSaveAsActivity(false);
            message.setSubject('Renewal due: ' + opportunity.Name);
            message.setPlainTextBody(
                'The renewal for opportunity "' + opportunity.Name +
                '" is due on ' + String.valueOf(opportunity.CloseDate) + '.'
            );

            messages.add(message);
        }

        if (messages.isEmpty()) {
            return 0;
        }

        Messaging.SendEmailResult[] results =
            Messaging.sendEmail(messages, false);

        Integer successfulCount = 0;
        for (Messaging.SendEmailResult result : results) {
            if (result.isSuccess()) {
                successfulCount++;
            }
        }

        return successfulCount;
    }
}
