import { LightningElement, api, wire } from 'lwc';
import { getRecord, getFieldValue } from 'lightning/uiRecordApi';
import NAME_FIELD from '@salesforce/schema/Account.Name';
import INDUSTRY_FIELD from '@salesforce/schema/Account.Industry';
import ANNUAL_REVENUE_FIELD from '@salesforce/schema/Account.AnnualRevenue';
import OWNER_NAME_FIELD from '@salesforce/schema/Account.Owner.Name';

const FIELDS = [
    NAME_FIELD,
    INDUSTRY_FIELD,
    ANNUAL_REVENUE_FIELD,
    OWNER_NAME_FIELD
];

export default class AccountHeader extends LightningElement {
    _recordId;
    account;
    error;

    @api
    get recordId() {
        return this._recordId;
    }

    set recordId(value) {
        if (value !== this._recordId) {
            this.account = undefined;
            this.error = undefined;
            this._recordId = value;
        }
    }

    @wire(getRecord, { recordId: '$recordId', fields: FIELDS })
    wiredAccount({ data, error }) {
        this.account = data;
        this.error = error;
    }

    get isLoading() {
        return !this.account && !this.error;
    }

    get hasError() {
        return Boolean(this.error);
    }

    get errorMessage() {
        return this.error?.body?.message;
    }

    get accountName() {
        return this.account
            ? getFieldValue(this.account, NAME_FIELD)
            : undefined;
    }

    get industry() {
        return this.account
            ? getFieldValue(this.account, INDUSTRY_FIELD)
            : undefined;
    }

    get annualRevenue() {
        return this.account
            ? getFieldValue(this.account, ANNUAL_REVENUE_FIELD)
            : undefined;
    }

    get ownerName() {
        return this.account
            ? getFieldValue(this.account, OWNER_NAME_FIELD)
            : undefined;
    }
}
