```javascript
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

export default class ContactSearch extends LightningElement {
    contacts = [];
    errorMessage = '';
    debounceTimeout;
    searchVersion = 0;

    handleChange(event) {
        const searchTerm = (event.target.value || '').trim();

        clearTimeout(this.debounceTimeout);
        this.debounceTimeout = undefined;

        // Invalidate in-flight responses as soon as the input changes.
        const version = ++this.searchVersion;
        this.errorMessage = '';

        if (searchTerm.length < 2) {
            this.contacts = [];
            return;
        }

        this.debounceTimeout = setTimeout(() => {
            this.debounceTimeout = undefined;
            this.performSearch(searchTerm, version);
        }, 300);
    }

    async performSearch(searchTerm, version) {
        if (!this.isConnected || version !== this.searchVersion) {
            return;
        }

        try {
            const contacts = await searchContacts({ searchTerm });

            if (!this.isConnected || version !== this.searchVersion) {
                return;
            }

            this.contacts = contacts || [];
            this.errorMessage = '';
        } catch (error) {
            if (!this.isConnected || version !== this.searchVersion) {
                return;
            }

            this.contacts = [];
            this.errorMessage =
                error?.body?.message || 'Unable to search contacts.';
        }
    }

    disconnectedCallback() {
        clearTimeout(this.debounceTimeout);
        this.debounceTimeout = undefined;

        // Also ignore responses from requests started before removal.
        this.searchVersion += 1;
    }
}
