import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    stats;
    errorMessage;

    _connected = false;
    _connectionVersion = 0;
    _requestInFlight = false;
    _pollingInterval;

    get waiting() {
        return this.stats?.waiting;
    }

    get longestWaitMinutes() {
        return this.stats?.longestWaitMinutes;
    }

    connectedCallback() {
        if (this._connected) {
            return;
        }

        this._connected = true;
        this._connectionVersion += 1;
        this.stats = undefined;
        this.errorMessage = undefined;

        document.addEventListener(
            'visibilitychange',
            this._handleVisibilityChange
        );
        this._handleVisibilityChange();
    }

    disconnectedCallback() {
        this._connected = false;
        this._connectionVersion += 1;
        this._stopPolling();

        document.removeEventListener(
            'visibilitychange',
            this._handleVisibilityChange
        );

        // Preserve the in-flight flag until any outstanding request settles.
        // Reconnecting must not allow an overlapping request.
    }

    _handleVisibilityChange = () => {
        this._stopPolling();

        if (!this._connected || document.visibilityState === 'hidden') {
            return;
        }

        this._refreshStats();
        this._pollingInterval = setInterval(() => {
            this._refreshStats();
        }, REFRESH_INTERVAL_MS);
    };

    _stopPolling() {
        if (this._pollingInterval !== undefined) {
            clearInterval(this._pollingInterval);
            this._pollingInterval = undefined;
        }
    }

    async _refreshStats() {
        if (
            !this._connected ||
            document.visibilityState === 'hidden' ||
            this._requestInFlight
        ) {
            return;
        }

        this._requestInFlight = true;
        const connectionVersion = this._connectionVersion;

        try {
            const stats = await getQueueStats();

            if (
                this._connected &&
                connectionVersion === this._connectionVersion
            ) {
                this.stats = stats;
                this.errorMessage = undefined;
            }
        } catch (error) {
            if (
                this._connected &&
                connectionVersion === this._connectionVersion
            ) {
                this.errorMessage =
                    error?.body?.message ||
                    error?.message ||
                    'Unable to load queue statistics.';
            }
        } finally {
            this._requestInFlight = false;
        }
    }
}
