import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

const PERSONAL_EMAIL_DOMAINS = new Set([
    'gmail.com',
    'yahoo.com',
    'hotmail.com',
    'outlook.com'
]);

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';
    isSubmitting = false;

    handleChange(event) {
        const field = event.currentTarget.dataset.field;
        this[field] = event.detail.value;
    }

    async handleRegister() {
        if (this.isSubmitting) {
            return;
        }

        const emailInput = this.template.querySelector(
            'lightning-input[data-field="email"]'
        );
        const domain = this.email.trim().split('@').pop().toLowerCase();

        emailInput.setCustomValidity(
            PERSONAL_EMAIL_DOMAINS.has(domain)
                ? 'Use your work email address.'
                : ''
        );

        let allValid = true;
        this.template.querySelectorAll('lightning-input').forEach((input) => {
            if (!input.reportValidity()) {
                allValid = false;
            }
        });

        if (!allValid) {
            return;
        }

        this.isSubmitting = true;

        try {
            await register({
                fullName: this.fullName,
                email: this.email,
                company: this.company
            });

            this.dispatchEvent(
                new ShowToastEvent({
                    variant: 'success',
                    title: 'Registered'
                })
            );
        } catch (error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    variant: 'error',
                    title: 'Registration failed',
                    message: error.body.message
                })
            );
