public with sharing class EmployerService {
    /**
     * Sets employers through NPSP's standard primary-affiliation mechanism.
     * NPSP manages the new/current affiliation and retires the previous primary
     * affiliation. Contact.AccountId is deliberately left unchanged.
     *
     * Requires the caller to have access to every supplied Contact and permission
     * to read and update Contact.npsp__Primary_Affiliation__c.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        for (Id contactId : employerByContactId.keySet()) {
            Id organizationId = employerByContactId.get(contactId);

            if (contactId == null ||
                contactId.getSObjectType() != Contact.SObjectType) {
                throw new IllegalArgumentException(
                    'Each employer-map key must be a non-null Contact Id.'
                );
            }

            if (organizationId == null ||
                organizationId.getSObjectType() != Account.SObjectType) {
                throw new IllegalArgumentException(
                    'Each employer-map value must be a non-null Organization Account Id.'
                );
            }
        }

        List<Contact> contacts = [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :employerByContactId.keySet()
            WITH USER_MODE
        ];

        // Do not silently process only part of the requested set.
        if (contacts.size() != employerByContactId.size()) {
            throw new IllegalArgumentException(
                'One or more requested Contacts do not exist or are not accessible.'
            );
        }

        List<Contact> changes = new List<Contact>();
        for (Contact existingContact : contacts) {
            Id organizationId = employerByContactId.get(existingContact.Id);

            if (existingContact.npsp__Primary_Affiliation__c != organizationId) {
                changes.add(new Contact(
                    Id = existingContact.Id,
                    npsp__Primary_Affiliation__c = organizationId
                ));
            }
        }

        if (!changes.isEmpty()) {
            // One atomic, bulk update. NPSP's automation handles affiliations;
            // do not insert affiliations or move Contacts out of households.
            Database.update(changes, true, AccessLevel.USER_MODE);
        }
    }
}
