public with sharing class RecurringGiftService {
    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    private static final Set<String> PAYMENT_METHODS = new Set<String>{
        'Credit Card', 'ACH', 'Check'
    };

    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> donationIds = new List<Id>();

        if (requests == null || requests.isEmpty()) {
            return donationIds;
        }

        // Validate the entire batch before attempting any DML.
        Boolean needsLastDayOption = false;
        for (Integer i = 0; i < requests.size(); i++) {
            validateRequest(requests[i], i + 1);
            if (requests[i].dayOfMonth == 31) {
                needsLastDayOption = true;
            }
        }

        String lastDayOption = needsLastDayOption
            ? getLastDayOfMonthValue()
            : null;

        Date establishedDate = Date.today();
        List<npe03__Recurring_Donation__c> donations =
            new List<npe03__Recurring_Donation__c>();

        for (GiftRequest request : requests) {
            Boolean isOpenEnded =
                request.installments == null || request.installments == 0;

            donations.add(new npe03__Recurring_Donation__c(
                npe03__Contact__c = request.contactId,
                npe03__Amount__c = request.amount,
                npe03__Date_Established__c = establishedDate,
                npe03__Installment_Period__c = 'Monthly',
                npsp__InstallmentFrequency__c = 1,
                npsp__Day_of_Month__c = request.dayOfMonth == 31
                    ? lastDayOption
                    : String.valueOf(request.dayOfMonth),
                npsp__StartDate__c = request.startDate,
                npsp__RecurringType__c = isOpenEnded ? 'Open' : 'Fixed',
                npe03__Installments__c = isOpenEnded
                    ? null
                    : request.installments,
                npsp__Status__c = 'Active',
                npsp__PaymentMethod__c = request.paymentMethod
            ));
        }

        // Enhanced NPSP owns end-date calculation, next-payment dates and
        // installment Opportunity generation. Do not set legacy scheduling
        // controls or create Opportunities here.
        //
        // One all-or-none DML statement, enforcing the caller's CRUD, FLS
        // and record-access permissions.
        insert as user donations;

        // DML populates the original records' Ids without changing list order.
        for (npe03__Recurring_Donation__c donation : donations) {
            donationIds.add(donation.Id);
        }

        return donationIds;
    }

    private static void validateRequest(
        GiftRequest request,
        Integer requestNumber
    ) {
        String prefix = 'Request ' + requestNumber + ': ';

        if (request == null) {
            throw new RecurringGiftException(prefix + 'Request cannot be null.');
        }

        if (request.contactId == null) {
            throw new RecurringGiftException(prefix + 'Contact is required.');
        }

        if (request.contactId.getSObjectType() != Contact.SObjectType) {
            throw new RecurringGiftException(
                prefix + 'contactId must identify a Contact.'
            );
        }

        if (request.amount == null || request.amount <= 0) {
            throw new RecurringGiftException(
                prefix + 'Amount must be greater than zero.'
            );
        }

        if (
            request.dayOfMonth == null ||
            request.dayOfMonth < 1 ||
            request.dayOfMonth > 31
        ) {
            throw new RecurringGiftException(
                prefix + 'dayOfMonth must be between 1 and 31.'
            );
        }

        if (request.startDate == null) {
            throw new RecurringGiftException(prefix + 'Start date is required.');
        }

        if (request.installments != null && request.installments < 0) {
            throw new RecurringGiftException(
                prefix + 'Installments cannot be negative.'
            );
        }

        if (!PAYMENT_METHODS.contains(request.paymentMethod)) {
            throw new RecurringGiftException(
                prefix + 'Payment method must be Credit Card, ACH or Check.'
            );
        }
    }

    private static String getLastDayOfMonthValue() {
        // Enhanced Day of Month contains numeric days and one special
        // last-day option. Resolve its API value rather than relying on a
        // translated label or the legacy Always Use Last Day checkbox.
        Pattern numericDay = Pattern.compile('^[0-9]+$');
        String lastDayValue;

        for (
            Schema.PicklistEntry entry :
            npe03__Recurring_Donation__c.npsp__Day_of_Month__c
                .getDescribe()
                .getPicklistValues()
        ) {
            String value = entry.getValue();

            if (
                !entry.isActive() ||
                String.isBlank(value) ||
                numericDay.matcher(value).matches()
            ) {
                continue;
            }

            if (lastDayValue != null) {
                throw new RecurringGiftException(
                    'Enhanced Recurring Donations has an ambiguous ' +
                    'last-day-of-month picklist configuration.'
                );
            }

            lastDayValue = value;
        }

        if (lastDayValue == null) {
            throw new RecurringGiftException(
                'Enhanced Recurring Donations has no active ' +
                'last-day-of-month option.'
            );
        }

        return lastDayValue;
    }
}
