public with sharing class PaymentPlanService {
    public class PaymentPlanException extends Exception {}

    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException(
                'The number of payments must be at least one.'
            );
        }
        if (opportunityId == null ||
            opportunityId.getSObjectType() != Opportunity.SObjectType) {
            throw new PaymentPlanException('A valid Opportunity Id is required.');
        }
        if (firstPaymentDate == null) {
            throw new PaymentPlanException('The first payment date is required.');
        }

        // CurrencyIsoCode exists only in multicurrency orgs. New installments
        // must use the pledge's currency, not the running user's default.
        Boolean hasCurrency = Opportunity.SObjectType.getDescribe()
            .fields.getMap().containsKey('CurrencyIsoCode');

        // Lock the parent first to serialize concurrent calls for this pledge.
        // User mode enforces sharing, CRUD, and field-level security.
        List<Opportunity> opportunities = Database.queryWithBinds(
            'SELECT Id, Amount, IsClosed' +
            (hasCurrency ? ', CurrencyIsoCode' : '') +
            ' FROM Opportunity WHERE Id = :opportunityId FOR UPDATE',
            new Map<String, Object>{ 'opportunityId' => opportunityId },
            AccessLevel.USER_MODE
        );

        if (opportunities.isEmpty()) {
            throw new PaymentPlanException(
                'The opportunity does not exist or is not accessible.'
            );
        }

        Opportunity pledge = opportunities[0];
        if (pledge.IsClosed) {
            throw new PaymentPlanException(
                'Installments cannot be scheduled for a closed opportunity.'
            );
        }
        if (pledge.Amount == null) {
            throw new PaymentPlanException(
                'The opportunity must have a positive outstanding amount.'
            );
        }

        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id, npe01__Payment_Amount__c,
                   npe01__Paid__c, npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            WITH USER_MODE
            FOR UPDATE
        ];

        Decimal outstanding = pledge.Amount;
        List<npe01__OppPayment__c> paymentsToDelete =
            new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c payment : existingPayments) {
            // A payment marked both paid and written off is counted only once.
            if (payment.npe01__Paid__c == true ||
                payment.npe01__Written_Off__c == true) {
                if (payment.npe01__Payment_Amount__c != null) {
                    outstanding -= payment.npe01__Payment_Amount__c;
                }
            } else {
                paymentsToDelete.add(payment);
            }
        }

        if (outstanding <= 0) {
            throw new PaymentPlanException(
                'The opportunity must have a positive outstanding amount.'
            );
        }

        Integer remainingDmlRows =
            Limits.getLimitDmlRows() - Limits.getDmlRows();
        if (numberOfPayments > remainingDmlRows - paymentsToDelete.size()) {
            throw new PaymentPlanException(
                'The installment plan exceeds the remaining DML row limit.'
            );
        }

        Decimal regularAmount = (outstanding / numberOfPayments)
            .setScale(2, RoundingMode.DOWN);
        Decimal remainder = outstanding - regularAmount * numberOfPayments;

        // Build the entire plan before changing any records.
        List<npe01__OppPayment__c> installments =
            new List<npe01__OppPayment__c>();

        for (Integer i = 0; i < numberOfPayments; i++) {
            npe01__OppPayment__c installment = new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c =
                    regularAmount +
                    (i == numberOfPayments - 1 ? remainder : 0),
                npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                npe01__Paid__c = false,
                npe01__Written_Off__c = false
            );

            if (hasCurrency) {
                installment.put(
                    'CurrencyIsoCode',
                    pledge.get('CurrencyIsoCode')
                );
            }

            installments.add(installment);
        }

        // Roll back both operations if either fails, even when a caller
        // catches the exception and continues its transaction.
        Savepoint planSavepoint = Database.setSavepoint();
        try {
            if (!paymentsToDelete.isEmpty()) {
                Database.delete(
                    paymentsToDelete,
                    true,
                    AccessLevel.USER_MODE
                );
            }

            Database.insert(installments, true, AccessLevel.USER_MODE);
        } catch (Exception e) {
            Database.rollback(planSavepoint);
            throw new PaymentPlanException(
                'Unable to schedule installments: ' + e.getMessage(),
                e
            );
        }

        // Insert populates the IDs without changing the list's schedule order.
        return installments;
    }
}
