@IsTest
private class TA_Opportunity_GuardAmountDecreaseTest {
    @IsTest
    static void reductionGreaterThanHalfIsRejected() {
        Id opportunityId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldRecord = new Opportunity(
            Id = opportunityId,
            Amount = 1000
        );
        Opportunity newRecord = new Opportunity(
            Id = opportunityId,
            Amount = 499
        );

        new TA_Opportunity_GuardAmountDecrease().beforeUpdate(
            new List<Opportunity>{ newRecord },
            new List<Opportunity>{ oldRecord }
        );

        assertRuleError(newRecord, 'Reduction from 1000 to 499');
        assertNoErrors(oldRecord, 'Old record must remain unchanged');
    }

    @IsTest
    static void reductionExactlyHalfIsAccepted() {
        Id opportunityId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Opportunity oldRecord = new Opportunity(
            Id = opportunityId,
            Amount = 1000
        );
        Opportunity newRecord = new Opportunity(
